(()=>{
'use strict';
const root=document.getElementById('infra-observer'),content=root.querySelector('#io-content'),feedback=root.querySelector('#io-feedback'),inv=window.InfraInventory,ops=window.InfraOps,C=window.InfraWorkspaceCore;
const {esc,table,box,badge,field,number}=inv.helpers,db=()=>inv.data();
const directorySeed=[{id:'wecom:demo-zhangchen',name:'张晨',department:'技术中心 / 基础设施',position:'系统运维',pinyin:'zhangchen',source:'wecom',active:true},{id:'wecom:demo-linyue',name:'林悦',department:'技术中心 / 应用研发',position:'应用负责人',pinyin:'linyue',source:'wecom',active:true},{id:'wecom:demo-wanghang',name:'王航',department:'技术中心 / 数据平台',position:'数据库运维',pinyin:'wanghang',source:'wecom',active:true},{id:'wecom:demo-zhangchen2',name:'张晨',department:'业务中心 / 财务部',position:'财务系统使用人',pinyin:'zhangchen',source:'wecom',active:true},{id:'wecom:demo-lixia',name:'李夏',department:'综合管理 / IT 支持',position:'IT 工程师',pinyin:'lixia',source:'wecom',active:true},{id:'custom:vendor-demo',name:'陈师傅',department:'外部维保',position:'设备维护',source:'custom',active:true}];
let state={version:1,people:structuredClone(directorySeed),assignments:{},theme:'cloud',density:'comfortable',connection:{corpId:'',agentId:'',credential:'',scope:'授权部门',status:'未连接'},syncAt:null,migrated:false};
try{const v=JSON.parse(localStorage.getItem('infrascope.workspace.v1'));if(v?.version===1)state={...state,...v};}catch{}
let active='overview',directoryFilter='全部',peopleQuery='',groupQuery='',groupFilter='全部',groupSelected=null,rankSort='total',rankScope='出口',rankRunning=true,tick=0,lastTick=Date.now(),liveSamples=[],pickerIds=[],pickerTarget=null;
const small=t=>`<span class="wk-small">${esc(t)}</span>`;
const btn=(label,action,id='',kind='',cls='')=>`<button type="button" data-wk="${action}" data-id="${esc(id)}" data-kind="${esc(kind)}" class="${cls}">${label}</button>`;
const icon=(name,cls='')=>{const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',server:'M4 3h16v7H4z M4 14h16v7H4z M7 6h.01 M7 17h.01 M11 6h6 M11 17h6',box:'m12 3 9 5v9l-9 5-9-5V8z M3 8l9 5 9-5 M12 13v9 M7 5.8l9 5',activity:'M3 12h4l3-8 4 16 3-8h4',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c5 5 5 13 0 18 M12 3c-5 5-5 13 0 18',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2',alert:'m12 3 10 18H2z M12 9v5 M12 17h.01',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17 3a4 4 0 0 1 0 8 M18 14a4 4 0 0 1 4 4v3',network:'M3 3h7v6H3z M14 15h7v6h-7z M3 15h7v6H3z M6.5 9v3H18v3 M6.5 12v3',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5z M10 21h4',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',search:'M15 15l6 6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',chevron:'m9 5 7 7-7 7',arrow:'M4 12h16 M14 6l6 6-6 6',check:'m5 12 4 4L19 6',sun:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 1v3 M12 20v3 M1 12h3 M20 12h3 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12',mail:'M3 5h18v14H3z M3 5l9 8 9-8',log:'M5 3h14v18H5z M8 7h8 M8 12h8 M8 17h5'};return `<svg class="wk-icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.grid}"/></svg>`;};
function persist(message){try{localStorage.setItem('infrascope.workspace.v1',JSON.stringify(state));if(message)feedback.textContent=message+' 已保存在当前浏览器。';}catch{if(message)feedback.textContent=message+' 浏览器存储不可用，仅本次会话保留。';}}
function people(ids){return (ids||[]).map(id=>state.people.find(p=>p.id===id)).filter(Boolean);}
function assignmentIds(kind,x){return state.assignments[kind+':'+x.id]||x.userIds||[];}
function chip(p){return `<span class="wk-person ${p.source==='custom'?'custom':''}"><span class="wk-person-avatar">${esc(p.name.slice(0,1))}</span><span>${esc(p.name)}</span><span class="wk-person-source">${p.source==='wecom'?'企微':'自定义'}</span></span>`;}
function personCell(kind,x){const list=people(assignmentIds(kind,x));return `<div class="wk-person-stack">${list.length?list.slice(0,2).map(chip).join(''):'<span class="wk-unassigned">未分配使用人</span>'}${list.length>2?small('另 '+(list.length-2)+' 人'):''}</div>${btn(list.length?'调整':'指定使用人','assign',x.id,kind,'link-button')}`;}
function personSearch(kind,x){return people(assignmentIds(kind,x)).map(p=>[p.name,p.department,p.id].join(' ')).join(' ');}
function personDetail(kind,x){if(!['devices','switches'].includes(kind))return '';const list=people(assignmentIds(kind,x));return `<section class="box wk-assignment-strip"><div class="wk-person-lead">${icon('people')}<div><strong>设备使用人</strong>${small('使用人与运维负责组分别管理')}</div></div><div class="wk-person-stack">${list.length?list.map(p=>`<div>${chip(p)}${small(p.department+(p.active===false?' · 已停用':''))}</div>`).join(''):'<span class="wk-unassigned">待指定使用人</span>'}</div>${btn('分配 / @ 人员','assign',x.id,kind,'main')}</section>`;}
function assignmentField(kind,x){const ids=x?assignmentIds(kind,x):[];return `<div class="iv-section-title">使用人 · 企业微信组织 / 自定义人员</div><div class="iv-full wk-assignment-field"><input type="hidden" name="userIds" value="${esc(JSON.stringify(ids))}"><div id="wk-form-users" class="wk-person-stack">${people(ids).map(chip).join('')||'<span class="wk-unassigned">请选择至少一位使用人</span>'}</div>${btn('@ 选择使用人','form-assign',x?.id||'',kind)}<span class="iv-note">同名人员按部门和 UserID 区分；自定义人员不自动获得企业微信通知身份。</span></div>`;}
function validateAssignment(value){try{return C.uniquePeople(Array.isArray(value)?value:JSON.parse(value||'[]'),state.people).length>0;}catch{return false;}}
function onConfigured(kind,x){if(['devices','switches'].includes(kind)){state.assignments[kind+':'+x.id]=C.uniquePeople(x.userIds||[],state.people);persist();}if(kind==='containers')x.dockerName=C.groupName(x);}
function makeDialog(title,body,footer){root.querySelector('#wk-dialog')?.remove();const d=document.createElement('dialog');d.id='wk-dialog';d.className='iv-dialog wk-dialog';d.setAttribute('aria-labelledby','wk-dialog-title');d.innerHTML=`<header><div><div class="iv-kicker">WORKSPACE / PEOPLE</div><h2 id="wk-dialog-title">${esc(title)}</h2></div>${btn('×','close')}</header><div class="iv-form-body">${body}<div id="wk-error" class="iv-error" role="alert"></div></div><footer>${footer||btn('关闭','close')}</footer>`;root.append(d);d.showModal();return d;}
function openPicker(kind,id,fromForm=false){const x=(kind==='switches'?db().switches:db().servers).find(x=>x.id===id),form=root.querySelector('#iv-form');pickerTarget={kind,id,fromForm,fromOverview:!!content.querySelector('#wk-overview-traffic')};pickerIds=fromForm?JSON.parse(form.querySelector('[name="userIds"]').value):[...assignmentIds(kind,x)];makeDialog('@ 选择设备使用人',`<div class="wk-picker-search">${icon('search')}<label for="wk-person-query" class="wk-sr-only">搜索企业微信人员</label><input id="wk-person-query" placeholder="@姓名、部门、拼音或 UserID" autocomplete="off"></div><div class="wk-picker-label"><span>企业微信组织 · 演示通讯录</span><span>可选择多位使用人</span></div><div id="wk-people-results" class="wk-people-results" role="group" aria-label="可选人员"></div><div class="wk-picker-selected"><strong>已选择</strong><div id="wk-selected" class="wk-person-stack"></div></div><details class="wk-custom"><summary>组织中没有这个人？自定义添加</summary><form id="wk-custom-form"><div class="iv-form-grid">${field('姓名','name','',{placeholder:'例如：外部维保人员'})}${field('部门 / 单位','department','',{required:false,placeholder:'外部单位或自定义部门'})}${field('备注 / 职责','position','',{required:false,full:true})}</div><button type="submit" class="main">添加并选中</button><p class="iv-note">保存为自定义人员，不会伪造企业微信 UserID，也不会自动发送 @ 通知。</p></form></details>`,`<span class="muted">演示数据 · 不读取真实企业通讯录</span>${btn('取消','close')}${btn('确认使用人','confirm-people','','','main')}`);paintPeople('');root.querySelector('#wk-person-query').focus();root.querySelector('#wk-custom-form').addEventListener('submit',e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));const p={id:'custom:'+Date.now().toString(36),name:v.name.trim(),department:v.department.trim()||'未填写部门',position:v.position.trim(),source:'custom',active:true};if(!p.name)return;state.people.push(p);pickerIds.push(p.id);persist();paintPeople(root.querySelector('#wk-person-query').value);e.target.reset();});}
function paintPeople(query){const list=C.searchPeople(state.people,query);root.querySelector('#wk-people-results').innerHTML=list.length?list.map(p=>`<label class="wk-picker-row"><input type="checkbox" data-wk-person="${esc(p.id)}" ${pickerIds.includes(p.id)?'checked':''}><span class="wk-large-avatar">${esc(p.name.slice(0,1))}</span><span><strong>${esc(p.name)} <em>${p.source==='wecom'?'企业微信':'自定义'}</em></strong>${small(p.department+' · '+p.position)}${small(p.id)}</span>${icon('check')}</label>`).join(''):'<div class="iv-empty">没有匹配的人员，可以在下方自定义添加。</div>';root.querySelector('#wk-selected').innerHTML=people(pickerIds).map(chip).join('')||small('尚未选择');}
function confirmPeople(){const selected=C.uniquePeople(pickerIds,state.people);if(!selected.length){root.querySelector('#wk-error').textContent='请至少选择一位使用人。';return;}if(pickerTarget.fromForm){const f=root.querySelector('#iv-form');f.querySelector('[name="userIds"]').value=JSON.stringify(selected);f.querySelector('#wk-form-users').innerHTML=people(selected).map(chip).join('');}else{state.assignments[pickerTarget.kind+':'+pickerTarget.id]=selected;const x=(pickerTarget.kind==='switches'?db().switches:db().servers).find(s=>s.id===pickerTarget.id);x.userIds=selected;inv.save('使用人已更新。');persist('使用人已更新。');if(pickerTarget.fromOverview)renderOverview();else inv.refresh();}root.querySelector('#wk-dialog').close();}
function groups(){return C.groups(db().containers);}
function group(id){const g=groups().find(g=>g.id===id);return g?{...g,business:g.businesses.join(' / ')}:null;}
function header(title,subtitle,actions=''){content.dataset.studioTitle=title;root.querySelector('#studio-breadcrumb').textContent=title;root.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===active));try{history.replaceState(null,'','#'+active);}catch{}return `<div class="page-heading wk-heading"><div><div class="iv-kicker">INFRASCOPE / ${active==='overview'?'WORKSPACE':active==='containers'?'DOCKER GROUPS':active==='directory'?'PEOPLE & ORGANIZATION':'NETWORK TRAFFIC'}</div><h2>${esc(title)}</h2><div class="muted">${esc(subtitle)}</div></div><div class="page-actions">${actions}</div></div>`;}
function render(p){active=p;if(p==='overview')renderOverview();if(p==='containers'){groupSelected=null;renderGroups();}if(p==='directory')renderDirectory();if(p==='live-network')renderRanking();}
function groupRule(g){return `<button type="button" data-op="rules" data-kind="dockerGroups" data-id="${esc(g.id)}" class="wk-quiet">${icon('bell')} 分组告警策略</button>`;}
function renderGroups(){const all=groups(),shown=all.filter(g=>[g.name,...g.businesses,...g.hosts.map(id=>db().servers.find(s=>s.id===id)?.name||'')].join(' ').toLowerCase().includes(groupQuery.toLowerCase())&&(groupFilter==='全部'||(groupFilter==='需关注'?g.abnormal>0:g.unknown>0)));content.innerHTML=header('Docker 名称分组','同一个 Docker 名称，一个监控视图，一套告警策略。',btn(icon('box')+' 添加容器实例','add-container','','','main'))+`<div class="wk-metrics"><div><span>Docker 分组</span><strong>${all.length}<em>组</em></strong></div><div><span>容器实例</span><strong>${db().containers.length}<em>个</em></strong></div><div><span>承载服务器</span><strong>${new Set(db().containers.map(c=>c.host)).size}<em>台</em></strong></div><div><span>异常分组</span><strong class="wk-warn">${all.filter(g=>g.abnormal>0).length}<em>组</em></strong></div></div><div class="wk-section-header"><div><h3>全部 Docker 分组</h3><span class="muted">告警绑定分组，新实例自动继承</span></div><div class="wk-toolbar"><label class="wk-search">${icon('search')}<input id="wk-group-query" value="${esc(groupQuery)}" placeholder="搜索 Docker 名称、宿主机、业务"></label><select id="wk-group-filter" aria-label="筛选 Docker 分组"><option ${groupFilter==='全部'?'selected':''}>全部</option><option ${groupFilter==='需关注'?'selected':''}>需关注</option><option ${groupFilter==='状态未知'?'selected':''}>状态未知</option></select></div></div><div class="wk-group-grid">${shown.map(g=>`<section class="box wk-group-card"><div class="wk-group-top"><span class="wk-group-icon">${icon('box')}</span><div>${btn(esc(g.name),'group',g.id,'','wk-group-title')}${small(g.businesses.join(' / '))}</div>${badge(g.abnormal?'需关注':g.unknown?'状态待确认':'运行正常')}</div><div class="wk-group-numbers"><div><strong>${g.instances.length}</strong><span>容器实例</span></div><div><strong>${g.hosts.length}</strong><span>宿主机</span></div><div><strong>${g.cpu==null?'—':g.cpu.toFixed(1)}</strong><span>CPU 核数合计</span></div></div><div class="wk-group-hosts">${g.hosts.map(id=>`<span>${icon('server')}${esc(db().servers.find(s=>s.id===id)?.name||id)}</span>`).join('')}</div><div class="wk-group-footer">${groupRule(g)}${btn('查看组内实例 '+icon('arrow'),'group',g.id,'','link-button')}</div></section>`).join('')||'<div class="iv-empty">没有匹配的 Docker 分组。</div>'}</div><div class="wk-caption">按显式的“Docker 名称”归组；实例名称、容器 ID 和宿主机作为组内维度保留。相同名称跨主机合并，跨业务归组会在详情中提示。</div>`;}
function groupDetail(id){const g=group(id);if(!g)return;groupSelected=id;content.innerHTML=header(g.name,'Docker 分组 / '+g.business,btn('← 全部分组','containers')+groupRule(g))+`<section class="wk-group-hero"><div><div class="iv-kicker">ONE NAME · ALL INSTANCES</div><h3>${g.instances.length} 个实例，共享一套监控策略</h3><p>实例重建、重命名或扩容后，只要 Docker 分组名称保持一致，就会继续继承组策略。</p></div><span class="wk-hero-box">${icon('box')}</span></section>${g.businesses.length>1?'<div class="iv-callout">此名称跨多个业务归组，请确认它们应共享告警策略。需要隔离时，可修改实例的 Docker 分组名称。</div>':''}${box('组内实例',table(['容器实例 / ID','宿主机 / 使用人','镜像 / 端口','资源','状态','操作'],g.instances.map(c=>{const h=db().servers.find(s=>s.id===c.host);return [esc(c.name)+small(c.instance||'待发现'),esc(h?.name||'未知')+(h?small(personSearch('devices',h).split(' ').slice(0,1).join('')):''),esc(c.image)+small((c.maps||[]).map(m=>m.host+' → '+m.container+'/'+m.protocol).join('，')||'无端口映射'),(c.cpu??'—')+' 核'+small(c.ram||'等待采样'),badge(c.state),btn('实例详情','instance',c.id)];})))}`+box('分组策略与关联服务',`<div class="wk-policy-summary"><div>${icon('bell')}<strong>告警作用域：${esc(g.name)}</strong>${small('支持组内重启总数、异常实例数；实例不再单独配置策略')}</div>${groupRule(g)}</div>`+table(['服务','部署实例','入口','状态'],db().services.filter(s=>g.instances.some(c=>c.id===s.target)).map(s=>[esc(s.name),esc(db().containers.find(c=>c.id===s.target)?.name),esc(s.domain)+':'+s.port,badge(s.state)])),'iv-bottom');}
function renderDirectory(){const deps=[...new Set(state.people.map(p=>p.department))],list=C.searchPeople(state.people,peopleQuery).filter(p=>directoryFilter==='全部'||directoryFilter==='自定义人员'&&p.source==='custom'||p.department===directoryFilter);content.innerHTML=header('使用人与组织','资产、实际使用人和运维负责组，一起管理。',btn(icon('people')+' 自定义人员','custom-person')+btn('同步演示通讯录','sync-people','','','main'))+`<div class="wk-directory-banner"><span class="wk-wecom-logo">${icon('people')}</span><div><strong>企业微信组织架构</strong><p>当前使用演示通讯录；输入 @ 可按姓名、部门、拼音、UserID 选择人员。</p></div><span class="wk-connection">${state.connection.status==='已配置'?'配置草稿 · 未连接':'未连接真实企业'}</span>${btn('对接设置','connect','','','wk-quiet')}</div><div class="wk-directory-layout"><section class="box wk-departments"><div class="wk-section-header"><h3>组织与人员</h3><span>${state.people.length}</span></div>${btn(icon('people')+' 全部人员','department','全部','',directoryFilter==='全部'?'selected':'')}${deps.map(d=>btn(esc(d),'department',d,'',directoryFilter===d?'selected':'')).join('')}${btn('自定义人员','department','自定义人员','',directoryFilter==='自定义人员'?'selected':'')}<div class="wk-caption">上次演示同步<br>${state.syncAt?new Date(state.syncAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚未同步'}</div></section><section class="box"><div class="wk-section-header"><div><h3>${esc(directoryFilter)}</h3><span class="muted">${list.length} 位人员 · 全部为示例或本地录入</span></div><label class="wk-search">${icon('search')}<input id="wk-directory-query" value="${esc(peopleQuery)}" placeholder="@姓名 / 部门 / UserID"></label></div>${table(['人员 / 身份','部门 / 职责','关联设备','来源'],list.map(p=>[`<div class="wk-directory-person"><span class="wk-large-avatar">${esc(p.name.slice(0,1))}</span><div><strong>${esc(p.name)}</strong>${small(p.id)}</div></div>`,esc(p.department)+small(p.position),[...db().servers.map(x=>({...x,kindKey:'devices'})),...db().switches.map(x=>({...x,kindKey:'switches'}))].filter(x=>assignmentIds(x.kindKey,x).includes(p.id)).map(x=>btn(esc(x.name),'device',x.id,x.kindKey,'wk-device-link')).join('')||small('尚未分配'),p.source==='wecom'?'<span class="wk-source wecom">企业微信 · 示例</span>':'<span class="wk-source custom">自定义</span>']))}</section></div>`;}
function connectForm(){const c=state.connection,d=makeDialog('企业微信组织架构 · 对接配置',`<form id="wk-connect-form"><div class="iv-callout">这里只保存接入草稿。实际通讯录由后端在授权范围内同步，企业密钥不得存入浏览器。</div><div class="iv-form-grid" style="margin-top:20px">${field('企业 ID（CorpID）','corpId',c.corpId,{placeholder:'wwxxxxxxxx'})}${field('应用 AgentID','agentId',c.agentId,{placeholder:'1000002'})}${field('后端凭据引用（不填 Secret）','credential',c.credential,{full:true,placeholder:'vault://wecom/contact-sync'})}${field('同步范围','scope',c.scope,{options:['授权部门','指定部门']})}${field('同步模式','mode','单向同步',{options:['单向同步']})}</div><p class="iv-note">企业成员保存稳定 UserID；自定义人员保存本地 ID。浏览器中的 @ 选择不代表已向企业微信发送通知。</p><button type="submit" class="main">保存对接草稿</button></form>`);d.querySelector('#wk-connect-form').addEventListener('submit',e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!/^vault:\/\/[A-Za-z0-9/_-]+$/.test(v.credential)){d.querySelector('#wk-error').textContent='请填写 vault:// 开头的凭据引用，不能填写真实 Secret。';return;}state.connection={...v,status:'已配置'};persist('企业微信对接草稿已保存；未连接真实通讯录。');d.close();renderDirectory();});}
function customPersonForm(){const d=makeDialog('添加自定义使用人',`<form id="wk-person-form"><div class="iv-form-grid">${field('姓名','name','')}${field('部门 / 单位','department','',{required:false})}${field('职责 / 备注','position','',{required:false,full:true})}</div><p class="iv-note">适用于企业组织外的人员；不会自动映射企业微信身份。</p><button type="submit" class="main">保存人员</button></form>`);d.querySelector('#wk-person-form').addEventListener('submit',e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!v.name.trim())return;state.people.push({...v,name:v.name.trim(),department:v.department.trim()||'未填写部门',id:'custom:'+Date.now().toString(36),source:'custom',active:true});persist('自定义使用人已添加。');d.close();renderDirectory();});}
function liveRows(){const result=[];for(const [index,s]of db().servers.entries()){const a=ops.asset(s.id);if(!a?.discovered)continue;for(const [i,n]of a.interfaces.entries()){const included=a.monitor?.includes(n.id),egress=window.InfraOpsCore.egress(a.interfaces).includes(n.id);if(rankScope==='出口'&&!egress||rankScope==='已监控'&&!included)continue;const id=s.id+'/'+n.id,valid=/^在线|^运行异常/.test(a.status)&&!!a.sampledAt,scale=(index===4?5:index===0?2:index===3?1.5:.6)/(i+1);const rx=(72+35*Math.sin(tick*.47+index*1.6)+8*Math.cos(tick*.21+index))*scale,tx=(28+20*Math.cos(tick*.37+index))*scale;result.push({id,server:s.id,name:s.name,iface:n.id,ip:s.ip,business:s.business,users:assignmentIds('devices',s),rx:valid?Math.max(0,rx):null,tx:valid?Math.max(0,tx):null,at:lastTick,quality:valid?'valid':'missing',egress,included,kind:n.type});}}return result;}
function refreshSamples(){lastTick=Date.now();tick++;liveSamples=liveRows();}
function rankingTable(rows,limit){const sorted=C.rank(rows,rankSort,Date.now()).slice(0,limit||rows.length),maximum=Math.max(1,...sorted.filter(r=>C.valid(r,Date.now())).map(r=>rankSort==='rx'?r.rx:rankSort==='tx'?r.tx:r.rx+r.tx));return table(['排名','服务器 / 网卡','使用人','接收 ↓','发送 ↑','合计 / 当前速率','操作'],sorted.map((r,i)=>{const valid=C.valid(r,Date.now()),value=rankSort==='rx'?r.rx:rankSort==='tx'?r.tx:r.rx+r.tx;return [`<span class="wk-rank-number ${i<3&&valid?'top':''}">${valid?String(i+1).padStart(2,'0'):'—'}</span>`,btn(esc(r.name),'device',r.server,'devices','wk-device-link')+small(r.iface+' · '+(r.egress?'默认路由候选':r.kind)),people(r.users).map(chip).join('')||small('待分配'),valid?`<span class="wk-rx">${r.rx.toFixed(2)}</span>${small('Mbps')}`:'—',valid?`<span class="wk-tx">${r.tx.toFixed(2)}</span>${small('Mbps')}`:'—',valid?`<strong class="wk-rate-total">${(r.rx+r.tx).toFixed(2)} <em>Mbps</em></strong><div class="wk-ranking-bar"><span style="width:${value/maximum*100}%"></span></div>`:badge(r.quality==='missing'?'无有效数据':'样本已过期'),btn('历史回看','history',r.server,r.iface,'link-button')];}));}
function renderRanking(){if(!liveSamples.length)refreshSamples();content.innerHTML=header('实时流量排行','自动发现出口候选，流量最大的接口优先展示。',btn(rankRunning?'暂停模拟':'继续模拟','toggle-ranking','','','wk-quiet')+btn(icon('clock')+' 历史回溯','traffic','','','main'))+`<div class="wk-ranking-hero"><div><span class="wk-live-pill"><i></i> ${rankRunning?'模拟实时更新':'模拟已暂停'}</span><h3>把最忙的网络，放在最前面。</h3><p>默认按接收 + 发送总速率降序，每 2 秒生成一次模拟样本并重新排序。</p></div><div class="wk-ranking-key"><span>默认排序</span><strong>Rx + Tx <em>↓</em></strong><small>当前速率 · Mbps</small></div></div><section class="box wk-ranking-panel"><div class="wk-section-header"><div><h3>接口流量排名</h3><span class="muted" id="wk-rank-time"></span></div><div class="wk-toolbar"><label>排序<select id="wk-rank-sort"><option value="total" ${rankSort==='total'?'selected':''}>收发总速率 ↓</option><option value="rx" ${rankSort==='rx'?'selected':''}>接收速率 ↓</option><option value="tx" ${rankSort==='tx'?'selected':''}>发送速率 ↓</option></select></label><label>范围<select id="wk-rank-scope"><option ${rankScope==='出口'?'selected':''}>出口</option><option ${rankScope==='已监控'?'selected':''}>已监控</option><option ${rankScope==='全部接口'?'selected':''}>全部接口</option></select></label></div></div><div id="wk-ranking-table"></div></section><div class="wk-caption">当前速率不等于累计流量；物理口、网桥及 Bond 分开排名，不叠加。样本超过 10 秒或缺失时移到榜尾；暂停超过 10 秒会标记过期。这里展示模拟速率，真实排序需接入采集端。</div>`;paintRanking();}
function paintRanking(){const target=content.querySelector('#wk-ranking-table');if(target){target.innerHTML=rankingTable(liveSamples);content.querySelector('#wk-rank-time').textContent='样本 '+new Date(lastTick).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})+' CST · '+liveSamples.length+' 个接口';}const overview=content.querySelector('#wk-overview-traffic');if(overview){overview.innerHTML=miniRanking();const chip=content.querySelector('#wk-live-updated');if(chip)chip.textContent='模拟更新 '+new Date(lastTick).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});}}
function miniRanking(){const rows=C.rank(liveSamples,'total',Date.now()).slice(0,4),max=Math.max(1,...rows.map(r=>(r.rx||0)+(r.tx||0)));return rows.map((r,i)=>`<div class="wk-mini-rank"><span class="wk-rank-number ${i===0?'top':''}">${String(i+1).padStart(2,'0')}</span><div class="wk-mini-rank-name"><strong>${esc(r.name)}</strong>${small(r.iface+' · '+r.business)}<div class="wk-ranking-bar"><span style="width:${((r.rx||0)+(r.tx||0))/max*100}%"></span></div></div><div class="wk-mini-rank-rate">${C.valid(r,Date.now())?(r.rx+r.tx).toFixed(1):'—'}<small>Mbps</small></div></div>`).join('');}
function metric(label,value,unit,detail,ico,color=''){return `<section class="box wk-metric-card ${color}"><div class="wk-metric-label">${label}<span>${icon(ico)}</span></div><div class="wk-metric-value">${value}<em>${unit}</em></div><div class="wk-metric-bottom">${detail}</div></section>`;}
function renderOverview(){if(!liveSamples.length)refreshSamples();const servers=db().servers,gs=groups(),events=ops.events(),firing=events.filter(e=>!e.resolved),assigned=servers.filter(s=>assignmentIds('devices',s).length).length;content.innerHTML=header('运维工作台','从人到设备，从服务到流量。让每一次排查都有方向。',`<span class="wk-live-pill"><i></i><span id="wk-live-updated">模拟数据</span></span>`+btn('+ 添加服务器','add-server','','','main'))+`<section class="wk-hero"><div class="wk-hero-copy"><div class="wk-eyebrow">YOUR INFRASTRUCTURE, CONNECTED.</div><h3>每一台设备，<br>都有人负责。</h3><p>统一管理使用人、Docker 名称分组和业务入口。<br>最需要关注的流量与告警，直接呈现在眼前。</p><div class="wk-hero-actions">${btn('查看设备与使用人 '+icon('arrow'),'devices','','','main')}${btn('组织人员 '+icon('people'),'directory','','','wk-hero-secondary')}</div></div><div class="wk-orbit" aria-hidden="true"><div class="wk-orbit-ring one"></div><div class="wk-orbit-ring two"></div><div class="wk-orbit-center">${icon('grid')}<strong>InfraScope</strong><span>一个工作空间</span></div><div class="wk-orbit-node n1">${icon('server')}<span>设备</span></div><div class="wk-orbit-node n2">${icon('box')}<span>Docker</span></div><div class="wk-orbit-node n3">${icon('people')}<span>使用人</span></div><div class="wk-orbit-node n4">${icon('activity')}<span>网络</span></div></div><span class="wk-hero-edition">WORKSPACE / 05</span></section><div class="stats wk-overview-stats">${metric('纳管设备',servers.length+db().switches.length,'台',servers.length+' 台服务器与外设 · '+db().switches.length+' 台交换机','server')}${metric('Docker 名称分组',gs.length,'组',db().containers.length+' 个实例 · 按名称统一策略','box')}${metric('待处理告警',firing.length,'条',firing.filter(e=>e.severity==='严重').length+' 条严重 · 按对象检索','alert','warm')}${metric('使用人覆盖',assigned,' / '+servers.length,'设备使用人与运维组分开管理','people','mint')}</div><div class="wk-overview-grid"><section class="box"><div class="wk-section-header"><div><div class="wk-eyebrow">TRAFFIC LEADERBOARD</div><h3>当前流量 · TOP 接口</h3><span class="muted">收发总速率降序 / 模拟每 2 秒刷新</span></div>${btn('全部排行 '+icon('arrow'),'live-network','','','link-button')}</div><div id="wk-overview-traffic">${miniRanking()}</div><div class="wk-panel-footer">${icon('clock')} 支持从当前接口跳转历史时段回溯</div></section><section class="box"><div class="wk-section-header"><div><div class="wk-eyebrow">ATTENTION REQUIRED</div><h3>待关注事件</h3></div>${btn('告警看板 '+icon('arrow'),'alerts','','','link-button')}</div><div class="wk-incidents">${firing.slice(0,3).map(e=>`<button class="wk-incident" type="button" data-op="event" data-id="${esc(e.id)}"><span class="wk-severity ${e.severity==='严重'?'critical':''}">${icon('alert')}</span><span><strong>${esc(e.title)}</strong>${small(e.targetName+' · '+e.business)}<em>${esc(e.severity)} / ${e.ack?'已确认':'待确认'}</em></span>${icon('chevron')}</button>`).join('')||'<div class="iv-empty">暂无未恢复告警</div>'}</div><div class="wk-panel-footer">故障、确认与静默独立管理</div></section><section class="box wk-wide"><div class="wk-section-header"><div><div class="wk-eyebrow">ASSETS & PEOPLE</div><h3>设备与使用人</h3></div>${btn('全部设备 '+icon('arrow'),'devices','','','link-button')}</div>${table(['设备名称 / IP','系统 / 类型','使用人','业务归属','运行状态','操作'],servers.slice(0,4).map(s=>[btn(esc(s.name),'device',s.id,'devices','wk-device-link')+small(s.ip),esc(s.os)+small(s.kind),people(assignmentIds('devices',s)).map(chip).join('')||small('未分配'),esc(s.business),ops.rowStatus('devices',s),btn('@ 调整使用人','assign',s.id,'devices','link-button')]))}</section></div><div class="wk-caption">交互 Demo：设备、人员、告警和流量均为演示数据；不连接真实企业微信或生产设备。</div>`;}
function applyTheme(){document.body.classList.toggle('dark',state.theme==='midnight');root.dataset.theme=state.theme;root.dataset.density=state.density;const select=root.querySelector('#wk-theme');if(select)select.value=state.theme;const density=root.querySelector('#wk-density');if(density)density.value=state.density;}
function bootstrap(){if(!state.migrated){const defaults={s1:['wecom:demo-zhangchen'],s2:['wecom:demo-lixia'],s3:['wecom:demo-wanghang'],s4:['wecom:demo-zhangchen2','wecom:demo-linyue'],s5:['wecom:demo-zhangchen'],s6:['wecom:demo-wanghang'],s7:['wecom:demo-zhangchen2'],s8:['custom:vendor-demo'],w1:['wecom:demo-zhangchen'],w2:['wecom:demo-lixia']};for(const s of db().servers){state.assignments['devices:'+s.id]=s.userIds||defaults[s.id]||[];}for(const s of db().switches){state.assignments['switches:'+s.id]=s.userIds||defaults[s.id]||[];}db().containers.forEach(c=>c.dockerName=C.groupName(c));if(db().containers.some(c=>c.id==='c1')&&!db().containers.some(c=>c.id==='demo-c4'))db().containers.push({id:'demo-c4',name:'office-api-replica-02',dockerName:'office-api',host:'s4',business:'办公系统',image:'registry.example.com/office-api:2.4.1',project:'office-prod',network:'bridge',maps:[{host:8081,container:8080,protocol:'TCP'}],health:'/healthz · 10s',cpu:'0.6',ram:'360 MiB / 2 GiB',state:'运行 · 健康',instance:'d72e9b11a302'});if(db().containers.some(c=>c.id==='c2')&&!db().containers.some(c=>c.id==='demo-c5'))db().containers.push({id:'demo-c5',name:'redis-cache-replica',dockerName:'redis-cache',host:'s3',business:'办公系统',image:'redis:7-alpine',project:'office-prod',network:'bridge',maps:[{host:6380,container:6379,protocol:'TCP'}],health:'PING · 10s',cpu:'0.1',ram:'240 MiB / 1 GiB',state:'运行 · 健康',instance:'b24a1e91d600'});for(const [key,r]of Object.entries(ops.rules())){if(r.kind!=='containers')continue;const c=db().containers.find(c=>c.id===r.target);if(!c)continue;const name=C.groupName(c),newKey='dockerGroups:'+name+':'+r.metric;if(!ops.rules()[newKey])ops.rules()[newKey]={...r,key:newKey,kind:'dockerGroups',target:name,targetName:name,runtime:{bad:0,good:0,firing:false,state:'未评估'}};delete ops.rules()[key];}for(const g of groups()){const key='dockerGroups:'+g.name+':restart';if(!ops.rules()[key])ops.rules()[key]={key,kind:'dockerGroups',target:g.name,targetName:g.name,business:g.businesses.join(' / '),metric:'restart',label:'组内 10 分钟重启总数',unit:'次',op:'gt',threshold:3,recovery:1,fail:3,recover:2,severity:'警告',channel:'企业微信 + 邮件',receiver:'业务值班组',repeat:30,enabled:true,runtime:{bad:0,good:0,firing:false,state:'未评估'}};}state.migrated=true;inv.save('');feedback.textContent='';ops.persist();persist();}applyTheme();}
root.addEventListener('click',e=>{const b=e.target.closest('[data-wk]');if(!b)return;const a=b.dataset.wk,id=b.dataset.id,kind=b.dataset.kind;if(a==='close')root.querySelector('#wk-dialog')?.close();else if(a==='assign')openPicker(kind,id);else if(a==='form-assign')openPicker(kind,id,true);else if(a==='confirm-people')confirmPeople();else if(a==='custom-person')customPersonForm();else if(a==='connect')connectForm();else if(a==='sync-people'){for(const p of directorySeed.filter(p=>p.source==='wecom')){const existing=state.people.find(x=>x.id===p.id);if(existing)Object.assign(existing,p);else state.people.push(structuredClone(p));}state.syncAt=Date.now();persist('演示通讯录已同步；未调用真实企业微信。');renderDirectory();}else if(a==='department'){directoryFilter=id;renderDirectory();}else if(a==='group')groupDetail(id);else if(a==='instance')inv.render('containers',id);else if(a==='add-container')inv.addContainer();else if(a==='add-server'){inv.render('devices');inv.openForm();}else if(a==='device')inv.render(kind||'devices',id);else if(a==='history')ops.openTraffic(id,kind);else if(a==='toggle-ranking'){rankRunning=!rankRunning;if(rankRunning)refreshSamples();renderRanking();}else if(['overview','containers','directory','live-network'].includes(a))render(a);else if(['devices','alerts','traffic'].includes(a))root.querySelector('nav [data-page="'+a+'"]').click();});
root.addEventListener('change',e=>{if(e.target.dataset.wkPerson){const id=e.target.dataset.wkPerson;pickerIds=e.target.checked?[...new Set([...pickerIds,id])]:pickerIds.filter(x=>x!==id);root.querySelector('#wk-selected').innerHTML=people(pickerIds).map(chip).join('')||small('尚未选择');}if(e.target.id==='wk-group-filter'){groupFilter=e.target.value;renderGroups();}if(e.target.id==='wk-rank-sort'){rankSort=e.target.value;paintRanking();}if(e.target.id==='wk-rank-scope'){rankScope=e.target.value;refreshSamples();paintRanking();}if(e.target.id==='wk-theme'){state.theme=e.target.value;applyTheme();persist();}if(e.target.id==='wk-density'){state.density=e.target.value;applyTheme();persist();}});
root.addEventListener('input',e=>{if(e.target.id==='wk-person-query')paintPeople(e.target.value);if(e.target.id==='wk-group-query'){groupQuery=e.target.value;const pos=e.target.selectionStart;renderGroups();const input=content.querySelector('#wk-group-query');input.focus();input.setSelectionRange(pos,pos);}if(e.target.id==='wk-directory-query'){peopleQuery=e.target.value;const pos=e.target.selectionStart;renderDirectory();const input=content.querySelector('#wk-directory-query');input.focus();input.setSelectionRange(pos,pos);}});
window.InfraWorkspace={render,personCell,personDetail,personSearch,assignmentField,validateAssignment,onConfigured,group,icon};bootstrap();
setInterval(()=>{if(document.hidden)return;if(!content.querySelector('#wk-ranking-table')&&!content.querySelector('#wk-overview-traffic'))return;if(rankRunning)refreshSamples();paintRanking();},2000);
const entry=location.hash.slice(1);if(['directory','live-network'].includes(entry))window.addEventListener('load',()=>root.querySelector('nav [data-page="'+entry+'"]').click(),{once:true});
})();
